function CatHouseCatDataInfo:FreshUI(catData, isShowEffect)
    self.isShowEffect = isShowEffect
    --- 刷新猫名称
    self.TextName.text = catData.name

    --- 刷新猫种族
    ---@type CatHouseCatVo
    local catHouseCatVo = CfUtils.GetCfVo(AutoIds.IdSetting1906, "CatHouseCatVo", catData.catId)
    self.TextType.text  = catHouseCatVo.name

    if self.BirthdayText then
        ----领取猫后会出现birthday为0的情况的处理
        local p = '(%d+)-(%d+)-(%d+) (%d+):(%d+):(%d+)'
        local year, month, day, hour, min, sec = tostring(catData.birthday):match(p)
        self.BirthdayText.text = string.format("%s-%s-%s", year, month, day)--currentCatData.birthday
    end

    local age = checkNumber(catData.age)
    if self.CatPeriod then
        self.CatPeriodImgBg.Status = age
        self.CatPeriodTextTitle.Status = age
    end

    local isBaby = age == ConstantsCatHouse.BornType.Baby
    ---@type CatHouseComponent
    local component     = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
    local classifyGenes = component:Process2ClassifyGenes(catData.genes, isBaby)

    local AppearanceGo = self.Appearance.gameObject
    ---外观数据
    local appearanceGenes = classifyGenes[1]
    self:StopAppearanceCo()
    if appearanceGenes then
        self.appearanceCo = cs_coroutine.start(function()
            self:FreshGenesUI(appearanceGenes, self.appearanceNodes, AppearanceGo, isBaby, catData)
            self.appearanceCo = nil
        end)

    end
    if self.Tips then
        KTool.SetActive(self.Tips.gameObject, isBaby)
        CfUtils.PlayDelayShowAnimate(self.Tips.gameObject, #appearanceGenes + 1)
        self.Tips:SetAsLastSibling()
    end

    local partGo = self.Part.gameObject
    ---部件数据
    local partsGenes  = classifyGenes[2]
    local isShowPart  = next(partsGenes) ~= nil
    KTool.SetActive(self.Empty.gameObject, not isShowPart)
    KTool.SetActive(partGo, isShowPart)
    self:StopPartCo()
    if isShowPart then
        self.parCo = cs_coroutine.start(function()
            self:FreshGenesUI(partsGenes, self.partNodes, partGo, isBaby, catData)
        end)

    end

end

function CatHouseCatDataInfo:FreshGenesUI(genes, nodeList, parent, isBaby, catData)
    local geneCount = #genes
    local nodeCount = #nodeList
    local forTimes  = math.max(geneCount, nodeCount)
    for i = 1, forTimes, 1 do
        local node = nodeList[i]
        if node == nil then
            node = parent:AddChild(nodeList[1].gameObject)
            table.insert(nodeList, node)
        end
        local geneData   = genes[i]
        local isShowGene = geneData ~= nil
        KTool.SetActive(node.gameObject, isShowGene)
        if isShowGene then
            self:FreshGeneDataUI(node, geneData, isBaby, catData, i)
            
        end
    end
end

function CatHouseCatDataInfo:FreshGeneDataUI(geneNode, geneData, isBaby, catData, index)
    ---@type CatHouseDataNode
    local env = CfUtils.GetLuaScr(geneNode, CatHouseDataNodeEnvPath)
    if isNull(env) then return end
    if isBaby then
        env:FreshChild(geneData, catData)
    else
        env:FreshAdult(geneData, catData)
    end
    env:SetBtnCallBack(function ()
        local catGeneData = CfUtils.GetCfVo(AutoIds.IdSetting1902, "CatHouseCatDataVo", geneData.geneId)
        if isBaby and catGeneData.attributeIdList then
            local catAttrData = CfUtils.GetCfVo(AutoIds.IdSetting1901, "CatHouseCatAttributeVo", catGeneData.attributeIdList[1])
            GameUtils.Toast(localize("_name_达到_num_后进化解锁", { _name_ = catAttrData.name, _num_ = catGeneData.attributeNumList[1] }))
        else
            CatHouseMgr:GetInstance():ShowCatHousDataDetailsNode(geneNode, geneData)
        end
        
    end)
    local AnimRoot = geneNode.transform:Find("AnimRoot")
    local animator = AnimRoot.gameObject:GetComponent(AnimatorType)
    
    if not isNull(animator) then
        animator:Rebind()
        animator:Play(DefaultHash)
    end
    -- self:FreshAnim(geneNode, geneData, 0.1, 0.5, index - 1)
    --env:PlayAnimator(index - 1 , 0.1, 0.5, function()
    --    if self.isShowEffect then
    --        ---@type CatHouseCatDataVo
    --        local catGeneData = CfUtils.GetCfVo(AutoIds.IdSetting1902, "CatHouseCatDataVo", geneData.geneId)
    --        KTool.SetActive(geneNode.transform:Find(EffectEnum[catGeneData.kind]).gameObject, true)
    --    end
    --end)
end

function CatHouseCatDataInfo:FreshAnim(node, geneData, interval, initialTime, index)
    if index == 0 then
        coroutine.yield(Yielders.GetWaitForSeconds(initialTime))
    end
    local AnimRoot = node.transform:Find("AnimRoot")
    local animator = AnimRoot.gameObject:GetComponent(AnimatorType)
    if not isNull(animator) then
        animator:Rebind()
        animator:Play(index == 0 and "Default" or "Go")
    end
    if self.isShowEffect then
        ---@type CatHouseCatDataVo
        local catGeneData = CfUtils.GetCfVo(AutoIds.IdSetting1902, "CatHouseCatDataVo", geneData.geneId)
        KTool.SetActive(node.transform:Find(EffectEnum[catGeneData.kind]).gameObject, true)
    end
    coroutine.yield(Yielders.GetWaitForSeconds(interval * index))
end

